rnd = random.Random(20240607)
NAMES = ['accept', 'accept-encoding', 'cache-control', 'if-match', 'if-none-match',
         'pragma', 'vary', 'x-list-hop', 'x-list-a.b', 'user-agent', 'referer',
         'range', 'if-modified-since', 'x-plain', 'accept-language', 'authorization',
         'content-type', 'origin', 'x-list-', 'forwarded']
REPEATABLE = {'accept','accept-encoding','cache-control','if-match','if-none-match',
              'pragma','vary'}
def listname(n): return n.startswith('x-list-') and len(n) > 7

def rand_value(n):
    pool = 'abcXYZ019-_~.;/:&=?!$%\'*+, @'
    return ''.join(rnd.choice(pool) for _ in range(rnd.randint(0, 12)))

def rand_path():
    if rnd.random() < 0.08:
        return '*'
    segs = rnd.randint(1, 3)
    chars = "-._~!$&'()*+,;=:@aAbBzZ09"
    p = '/'
    for _ in range(segs):
        p += ''.join(rnd.choice(chars) for _ in range(rnd.randint(1, 6)))
        if rnd.random() < 0.3:
            p += '%' + ''.join(rnd.choice('0123456789abcdefAB') for _ in range(2))
        if rnd.random() < 0.4:
            p += '/'
    if rnd.random() < 0.4:
        p += '?' + ''.join(rnd.choice('ab=1&') for _ in range(rnd.randint(0, 8)))
    if p.startswith('//'):
        p = '/' + p[1:]
    if p == '*':
        p = '/x'
    return p

def rand_authority():
    kind = rnd.random()
    if kind < 0.4:
        return 'demo.test'
    if kind < 0.5:
        return '10.%d.%d.%d' % (rnd.randint(0,255), rnd.randint(0,255), rnd.randint(0,255))
    if kind < 0.6:
        return '[2001:db8::%x]' % rnd.randint(0, 15)
    if kind < 0.7:
        return 'alt%d.test' % rnd.randint(0, 3)
    if kind < 0.8:
        return 'demo.test:%d' % rnd.choice([80, 8080, 1, 65535, 443])
    return 'a-b%d.test' % rnd.randint(0, 5)

def build_stream(sid):
    """Return (events, expected_bytes or None if rejected-free construction)."""
    method = rnd.choice(['GET','HEAD','POST','PUT','PATCH','DELETE','OPTIONS'])
    scheme = rnd.choice(['http', 'https'])
    authority = rand_authority()
    path = rand_path()
    if path == '*':
        method = 'OPTIONS'
    use_host = rnd.random() < 0.25
    pairs = [[':method', method], [':scheme', scheme],
             [':authority' if not use_host else 'host', authority]]
    if rnd.random() < 0.2:
        pairs.append([':authority' if use_host else 'host', authority])  # both, identical
    body = bytes(rnd.randrange(256) for _ in range(rnd.choice([0, 1, 2, 5, 300, 70000])))
    body = body[:65536]
    chunked = rnd.random() < 0.5
    trailers = []
    if chunked and rnd.random() < 0.75:
        for _ in range(rnd.randint(1, 4)):
            name = 'x-audit-' + ''.join(rnd.choice('abcxyz09-') for _ in range(rnd.randint(1, 5)))
            trailers.append([name, rand_value(0)])
    cl_lines = []
    if not chunked and rnd.random() < 0.7:
        n = len(body)
        reps = rnd.choice([1, 1, 2])
        for _ in range(reps):
            members = [str(n)] * rnd.choice([1, 2])
            if rnd.random() < 0.4:
                members = [m.rjust(rnd.randint(len(m), len(m)+3), '0') for m in members]
            cl_lines.append(', '.join(members))
    regular = []
    for name in NAMES:
        reps = 0
        if name in REPEATABLE or listname(name):
            reps = rnd.choice([0, 0, 1, 2, 3])
        elif rnd.random() < 0.35:
            reps = 1
        for _ in range(reps):
            if name == 'content-length':
                continue
            if name == 'te':
                continue
            regular.append([name, rand_value(name)])
    for line in cl_lines:
        regular.append(['content-length', line])
    if rnd.random() < 0.6:
        ncookies = rnd.randint(1, 3)
        pos = rnd.randrange(len(regular) + 1)
        cookies = [[ 'cookie', 'k%d=v%d' % (i, i)] for i in range(ncookies)]
        regular[pos:pos] = cookies
    if rnd.random() < 0.5:
        regular.append(['te', 'trailers'])
    pairs += regular
    rnd.shuffle(regular) if False else None
    events = [{'sid': sid, 'type': 'headers', 'fields': pairs}]
    if body:
        cuts = sorted(rnd.randrange(1, len(body)) for _ in range(rnd.randint(0, 3)))
        prev = 0
        chunks = []
        for c in cuts + [len(body)]:
            chunks.append(body[prev:c]); prev = c
        for ch in chunks:
            events.append({'sid': sid, 'type': 'data', 'hex': ch.hex()})
    if chunked:
        events.append({'sid': sid, 'type': 'headers', 'fields': trailers})
    for _ in range(rnd.randint(0, 2)):
        events.insert(rnd.randrange(len(events)),
                      {'sid': sid, 'type': 'unknown', 'frame_type': 99, 'hex': 'cafe'})
    events.append({'sid': sid, 'type': 'fin'})

    # expected serialization, computed independently
    canon = test_canon(authority, scheme)
    assert canon is not None, authority
    lines = ['%s %s HTTP/1.1' % (method, path), 'host: ' + canon]
    cookies = [v for n, v in regular if n == 'cookie']
    emitted = False
    for n, v in regular:
        if n in ('content-length', 'te'):
            continue
        if n == 'cookie':
            if not emitted:
                emitted = True
                lines.append('cookie: ' + '; '.join(cookies))
            continue
        lines.append('%s: %s' % (n, v))
    out = ''.join(l + '\r\n' for l in lines).encode('latin-1')
    if not chunked:
        out += ('content-length: %d\r\n\r\n' % len(body)).encode() + body
    else:
        out += b'transfer-encoding: chunked\r\n'
        if trailers:
            names = []
            for n, _ in trailers:
                if n not in names:
                    names.append(n)
            out += ('trailer: ' + ', '.join(names) + '\r\n').encode()
        out += b'\r\n'
        if body:
            out += ('%x\r\n' % len(body)).encode() + body + b'\r\n'
        out += b'0\r\n'
        for n, v in trailers:
            out += ('%s: %s\r\n' % (n, v)).encode()
        out += b'\r\n'
    return events, out, scheme, canon, path, method

ROUTES = {}
